    static func dismantleNSView(_ v:WKWebView,coordinator:Coordinator){coordinator.requests.values.forEach{$0.cancel()};coordinator.requests.removeAll();v.configuration.userContentController.removeScriptMessageHandler(forName:"leaf");v.navigationDelegate=nil;v.stopLoading()}
    @MainActor final class Coordinator:NSObject,WKURLSchemeHandler,WKScriptMessageHandler,WKNavigationDelegate{
        let state:ReaderState,source:BookSource;var command:UUID?,requests:[ObjectIdentifier:Task<Void,Never>]=[:],stopped=Set<ObjectIdentifier>();init(state:ReaderState,source:BookSource){self.state=state;self.source=source}
        func webView(_ v:WKWebView,start t:WKURLSchemeTask){let id=ObjectIdentifier(t);requests[id]=Task{@MainActor in do{guard let u=t.request.url else{throw ReadError("Missing resource URL")};let d:Data;if u.host=="reader"{let p=Bundle.main.resourceURL?.appendingPathComponent("Reader"),root=p.flatMap{FileManager.default.fileExists(atPath:$0.path) ? $0:nil} ?? Bundle.module.url(forResource:"Reader",withExtension:nil)!,f=root.appendingPathComponent(String(u.path.dropFirst())).standardizedFileURL.resolvingSymlinksInPath();d=try await Task.detached{try Data(contentsOf:f)}.value}else if u.host=="book"{d=try await source.response(u)}else{throw ReadError("Unknown resource host")};guard !Task.isCancelled,requests[id] != nil,!stopped.contains(id) else{return};let mime=["js":"text/javascript","hhc":"text/html","hhk":"text/html"][u.pathExtension] ?? UTType(filenameExtension:u.pathExtension)?.preferredMIMEType ?? "application/octet-stream";t.didReceive(HTTPURLResponse(url:u,statusCode:200,httpVersion:"HTTP/1.1",headerFields:["Content-Type":mime,"Content-Length":String(d.count),"Access-Control-Allow-Origin":"*"])!);t.didReceive(d);t.didFinish()}catch{if !Task.isCancelled,requests[id] != nil{t.didFailWithError(error)}};requests.removeValue(forKey:id)}}
        func webView(_ v:WKWebView,stop t:WKURLSchemeTask){let id=ObjectIdentifier(t);stopped.insert(id);requests.removeValue(forKey:id)?.cancel()}
        func userContentController(_ c:WKUserContentController,didReceive m:WKScriptMessage){guard m.frameInfo.isMainFrame,let b=m.body as? [String:Any],let t=b["type"] as? String else{return};switch t{case"location":state.cfi=b["cfi"] as? String;state.fraction=b["fraction"] as? Double ?? 0;state.persist();case"toc","results":if let i=b["items"],let d=try? JSONSerialization.data(withJSONObject:i),let x=try? JSONDecoder().decode([ContentsItem].self,from:d){state.outline=x};if t=="results"{state.showContents=true};case"status":state.status=b["message"] as? String ?? "";case"error":state.error=b["message"] as? String ?? "Unable to render book";case"external":if let h=b["href"] as? String,let u=URL(string:h),["https","http","mailto"].contains(u.scheme){NSWorkspace.shared.open(u)};default:break}}
        func webView(_ v:WKWebView,decidePolicyFor a:WKNavigationAction,decisionHandler:@escaping(WKNavigationActionPolicy)->Void){decisionHandler(["leaf","blob","about","data"].contains(a.request.url?.scheme ?? "") ? .allow:.cancel)}
    }}
